import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageCircle, Send, X, ArrowRight } from 'lucide-react';
import { GoogleGenAI } from '@google/genai';

interface Message {
  role: 'user' | 'bot';
  text: string;
}

interface ChatbotProps {
  onOpenModal: () => void;
}

const Chatbot: React.FC<ChatbotProps> = ({ onOpenModal }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    {
      role: 'bot',
      text: "Hi, I’m Emily. I can explain how NodeArc works, or help you decide if automation makes sense for your business."
    }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...messages.map(m => ({
          role: m.role === 'bot' ? 'model' : 'user',
          parts: [{ text: m.text }]
        })), { role: 'user', parts: [{ text: userMessage }] }],
        config: {
          systemInstruction: `You are Emily, a clarity assistant for NodeArc AI. 
NodeArc AI designs and deploys production-grade automation systems for businesses.
Your tone is calm, professional, intelligent, and serious.
You are NOT a sales bot. You are a clarity assistant.
Simplify technical concepts like "orchestration" or "webhooks" only if asked.
Keep answers concise (max 2-3 sentences).
Do not use emojis.
If the user seems serious about automation, suggest a Strategy Call.
Transition example: "Based on this, a strategy call would make sense. You can request one here."`,
          temperature: 0.7,
        },
      });

      const botText = response.text || "I apologize, I'm having trouble connecting to my systems. Please request a strategy call for detailed assistance.";
      setMessages(prev => [...prev, { role: 'bot', text: botText }]);
    } catch (error) {
      console.error('Chatbot error:', error);
      setMessages(prev => [...prev, { role: 'bot', text: "I'm sorry, I'm currently experiencing technical difficulties. You may want to request a strategy call directly." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-8 right-8 z-[100] font-sans">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
            className="absolute bottom-20 right-0 w-80 md:w-96 bg-[#0A0A0A] border border-white/10 rounded-sm shadow-2xl flex flex-col h-[500px] overflow-hidden"
          >
            {/* Header */}
            <div className="p-4 border-b border-white/5 flex items-center justify-between bg-white/5">
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 bg-neutral-400 rounded-full animate-pulse" />
                <span className="text-xs font-mono uppercase tracking-widest text-neutral-400">Clarity Assistant: Emily</span>
              </div>
              <button onClick={() => setIsOpen(false)} className="text-neutral-500 hover:text-white transition-colors">
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-thin scrollbar-thumb-white/10">
              {messages.map((msg, idx) => (
                <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-3 text-sm leading-relaxed rounded-sm ${msg.role === 'user' ? 'bg-white text-black' : 'bg-white/5 text-neutral-300 border border-white/5'}`}>
                    {msg.text}
                    {msg.text.toLowerCase().includes('request one here') && (
                      <button
                        onClick={onOpenModal}
                        className="mt-2 flex items-center gap-1 text-xs font-bold uppercase tracking-wider text-white border-b border-white/20 hover:border-white transition-all w-fit"
                      >
                        Request Strategy Call <ArrowRight className="w-3 h-3" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className="bg-white/5 p-3 rounded-sm">
                    <div className="flex gap-1">
                      <div className="w-1.5 h-1.5 bg-neutral-600 rounded-full animate-bounce" />
                      <div className="w-1.5 h-1.5 bg-neutral-600 rounded-full animate-bounce [animation-delay:0.2s]" />
                      <div className="w-1.5 h-1.5 bg-neutral-600 rounded-full animate-bounce [animation-delay:0.4s]" />
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <div className="p-4 border-t border-white/5 bg-white/5">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                  placeholder="Ask a question..."
                  className="flex-1 bg-white/5 border border-white/10 rounded-sm px-4 py-2 text-sm text-white focus:outline-none focus:border-white/30 transition-colors"
                />
                <button
                  onClick={handleSend}
                  disabled={!input.trim() || isTyping}
                  className="bg-white text-black p-2 rounded-sm disabled:opacity-50 hover:bg-neutral-200 transition-colors"
                >
                  <Send className="w-4 h-4" />
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <button
        onClick={() => setIsOpen(!isOpen)}
        className="group flex items-center gap-3 bg-neutral-900 border border-white/10 text-white px-5 py-4 rounded-sm shadow-xl hover:bg-neutral-800 transition-all duration-300"
      >
        <span className="text-xs font-mono uppercase tracking-[0.2em] opacity-0 group-hover:opacity-100 transition-opacity duration-300">Ask Emily</span>
        <MessageCircle className="w-6 h-6" />
      </button>
    </div>
  );
};

export default Chatbot;

